  "sql": "WITH _cm_amount_sum_partition_by_customers_id AS (\n  SELECT\n    _stage_inner.\"orders.customers.id\" AS \"customers__id\",\n    _stage_inner.\"orders.amount_sum_partition_by_customers_id\" AS \"amount_sum_partition_by_customers_id\"\n  FROM (\n    SELECT\n      customers.id AS \"orders.customers.id\",\n      CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.amount_sum_partition_by_customers_id\"\n    FROM orders AS orders\n    LEFT JOIN customers AS customers\n      ON orders.customer_id = customers.id\n    GROUP BY\n      customers.id\n  ) AS _stage_inner\n)\nSELECT\n  CASE\n    WHEN NOT customers.id IS NULL\n    AND _cm_amount_sum_partition_by_customers_id.\"amount_sum_partition_by_customers_id\" > 2000\n    THEN 'high'\n    ELSE 'other'\n  END AS \"orders.grp\",\n  CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.sum_amount\",\n  COUNT(*) AS \"orders.count_all\"\nFROM orders AS orders\nLEFT JOIN customers AS customers\n  ON orders.customer_id = customers.id\nLEFT JOIN _cm_amount_sum_partition_by_customers_id\n  ON customers.id IS NOT DISTINCT FROM _cm_amount_sum_partition_by_customers_id.\"customers__id\"\nGROUP BY\n  CASE\n    WHEN NOT customers.id IS NULL\n    AND _cm_amount_sum_partition_by_customers_id.\"amount_sum_partition_by_customers_id\" > 2000\n    THEN 'high'\n    ELSE 'other'\n  END\nORDER BY\n  \"orders.grp\" ASC\nLIMIT 101"
